sp_widget.client_script:
function($scope, $timeout) {
  $scope.isFadingUltimos12Meses = false;
  $scope.dadosUltimos12Meses = $scope.data; 

  function ativarFade() {
    $scope.isFadingUltimos12Meses = true;
    $timeout(function() {
      $scope.isFadingUltimos12Meses = false;
    }, 500);
  }

  // Fade inicial (opcional)
  ativarFade();

  $scope.atualizarDados = function(novosDados) {
    ativarFade();
    $timeout(function() {
      $scope.dadosUltimos12Meses = novosDados;
    }, 500);
  };
}

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Roboto+Flex:opsz,wght@8..144,100..1000&display=swap');

/* --- Wrapper Principal (Animação e Layout) --- */
.financial-widget-wrapper {
  font-family: 'Roboto Flex', sans-serif;
  margin-top: 4rem; /* Alinhamento padrão */

  /* Lógica de Transição */
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
  transition: opacity 0.5s ease-in-out, transform 0.5s ease-in-out, visibility 0.5s ease-in-out;
}

.financial-widget-wrapper.fade-out {
  opacity: 0;
  visibility: hidden;
  transform: translateY(20px);
}

/* --- Estrutura Visual do Widget --- */
.financial-widget {
  border: 1px solid #ccc;
  border-radius: 4px;
  overflow: hidden;
  background-color: #fff;
}

.indicator-block {
  text-align: center;
  padding: 0;
}

.indicator-header {
  background-color: #EBEDF1;
  color: #021770;
  font-weight: 400;
  padding: 8px 10px;
  font-size: 14px;
  border-bottom: 1px solid #C7C7C7;
  font-family: 'Roboto Flex', sans-serif;
}

.indicator-value {
  color: #021770;
  font-size: 32px;
  font-weight: 400;
  padding: 10px 10px 15px;
  font-family: 'Roboto Flex', sans-serif;
}

/* Estilo para mensagem de "Nenhum dado" */
.indicator-value.small-text {
  font-size: 18px;
  color: #666;
  line-height: 1.5;
  padding: 20px;
}

/* --- Responsividade --- */
@media (max-width: 767px) {
  .financial-widget-wrapper {
    margin-top: 1rem;
  }
  .indicator-value {
    font-size: 24px;
  }
}

@media (min-width: 768px) and (max-width: 1023px) {
  .financial-widget-wrapper {
    margin-top: 2rem;
  }
}

@media (max-width: 350px) {
  .indicator-header {
    font-size: 12px;
  }
  .indicator-value {
    font-size: 20px;
    padding: 6px;
  }
}

sp_widget.script:
(function() {
   /*function formatarNumero(valor) {
  var resultado = (valor);
  resultado = resultado.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  return resultado;
}*/
	//R$ 32.565.714.370.5

	 function formatarNumero(valor) {
  if (typeof valor !== 'number') {
    valor = parseFloat(valor);
  }

  return valor.toFixed(2) // fixa duas casas decimais
              .replace('.', ',') // troca ponto decimal por vírgula
              .replace(/\B(?=(\d{3})+(?!\d))/g, '.'); // separador de milhar
}

  var gr = new GlideRecord('x_sded9_portal_t_0_u_rreo');
  gr.orderByDesc('u_ano');
  gr.orderByDesc('u_mes');
  gr.setLimit(12);
  gr.query();

  var soma = 0;
  var anoMaisRecente = null;

  while (gr.next()) {
    var valor = parseFloat(gr.getValue('rreo_according_to_lrf_fiscal_responsibility_law_2')) || 0;
    soma += valor;

    if (!anoMaisRecente) {
      anoMaisRecente = gr.getValue('u_ano');
    }
  }

  if (soma >= 0) {
    var valorFormatado = formatarNumero(soma);
    data.temDado = true;
    data.valorSoma = soma;
    data.valorSomaFormatado = valorFormatado;
    data.ano = anoMaisRecente;
    data.dados = [{
      ano: anoMaisRecente,
      valorSoma: soma,
      valorSomaFormatado: valorFormatado,
      temDado: true
    }];
  } else {
    data.temDado = false;
    data.ano = null;
    data.dados = [];
  }
})();
